class Solution:
    def elementInNums(self, nums, queries):
        n = len(nums)
        states = [list(nums)]
        cur = list(nums)
        for t in range(1, 2 * n):
            if t <= n:
                cur.pop(0)
            else:
                cur.append(nums[t - n - 1])
            states.append(list(cur))
        return [states[t % (2 * n)][i] if i < len(states[t % (2 * n)]) else -1 for t, i in queries]

