class Solution {
public:
    vector<int> elementInNums(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size();
        vector<vector<int>> st;
        st.push_back(nums);
        vector<int> cur = nums;
        for (int t = 1; t < 2 * n; t++) {
            if (t <= n) cur.erase(cur.begin());
            else cur.push_back(nums[t - n - 1]);
            st.push_back(cur);
        }
        vector<int> res;
        for (auto& q : queries) {
            auto& s = st[q[0] % (2 * n)];
            res.push_back(q[1] < (int)s.size() ? s[q[1]] : -1);
        }
        return res;
    }
};

