class Solution {
    public int[] elementInNums(int[] nums, int[][] queries) {
        int n = nums.length;
        List<int[]> st = new ArrayList<>();
        st.add(nums.clone());
        int[] cur = nums.clone();
        for (int t = 1; t < 2 * n; t++) {
            if (t <= n) cur = Arrays.copyOfRange(cur, 1, cur.length);
            else {
                int[] nx = Arrays.copyOf(cur, cur.length + 1);
                nx[cur.length] = nums[t - n - 1];
                cur = nx;
            }
            st.add(cur.clone());
        }
        int[] res = new int[queries.length];
        for (int j = 0; j < queries.length; j++) {
            int[] s = st.get(queries[j][0] % (2 * n));
            res[j] = queries[j][1] < s.length ? s[queries[j][1]] : -1;
        }
        return res;
    }
}

