var elementInNums = function(nums, queries) {
    const n = nums.length, st = [nums.slice()], cur = nums.slice();
    for (let t = 1; t < 2 * n; t++) {
        if (t <= n) cur.shift();
        else cur.push(nums[t - n - 1]);
        st.push(cur.slice());
    }
    return queries.map(([t, i]) => {
        const s = st[t % (2 * n)];
        return i < s.length ? s[i] : -1;
    });
};

